def get_openapi_path(
    *, route: routing.APIRoute, model_name_map: Dict[Type, str]
) -> Tuple[Dict, Dict, Dict]:
    path = {}
    security_schemes: Dict[str, Any] = {}
    definitions: Dict[str, Any] = {}
    assert route.methods is not None, "Methods must be a list"
    assert route.response_class, "A response class is needed to generate OpenAPI"
    route_response_media_type: Optional[str] = route.response_class.media_type
    if route.include_in_schema:
        for method in route.methods:
            operation = get_openapi_operation_metadata(route=route, method=method)
            parameters: List[Dict] = []
            flat_dependant = get_flat_dependant(route.dependant, skip_repeats=True)
            security_definitions, operation_security = get_openapi_security_definitions(
                flat_dependant=flat_dependant
            )
            if operation_security:
                operation.setdefault("security", []).extend(operation_security)
            if security_definitions:
                security_schemes.update(security_definitions)
            all_route_params = get_openapi_params(route.dependant)
            operation_parameters = get_openapi_operation_parameters(all_route_params)
            parameters.extend(operation_parameters)
            if parameters:
                operation["parameters"] = parameters
            if method in METHODS_WITH_BODY:
                request_body_oai = get_openapi_operation_request_body(
                    body_field=route.body_field, model_name_map=model_name_map
                )
                if request_body_oai:
                    operation["requestBody"] = request_body_oai
            if route.callbacks:
                callbacks = {}
                for callback in route.callbacks:
                    cb_path, cb_security_schemes, cb_definitions, = get_openapi_path(
                        route=callback, model_name_map=model_name_map
                    )
                    callbacks[callback.name] = {callback.path: cb_path}
                operation["callbacks"] = callbacks
            if route.responses:
                for (additional_status_code, response) in route.responses.items():
                    assert isinstance(
                        response, dict
                    ), "An additional response must be a dict"
                    field = route.response_fields.get(additional_status_code)
                    if field:
                        response_schema, _, _ = field_schema(
                            field, model_name_map=model_name_map, ref_prefix=REF_PREFIX
                        )
                        response.setdefault("content", {}).setdefault(
                            route_response_media_type or "application/json", {}
                        )["schema"] = response_schema
                    status_text: Optional[str] = status_code_ranges.get(
                        str(additional_status_code).upper()
                    ) or http.client.responses.get(int(additional_status_code))
                    response.setdefault(
                        "description", status_text or "Additional Response"
                    )
                    status_code_key = str(additional_status_code).upper()
                    if status_code_key == "DEFAULT":
                        status_code_key = "default"
                    operation.setdefault("responses", {})[status_code_key] = response
            status_code = str(route.status_code)
            operation.setdefault("responses", {}).setdefault(status_code, {})[
                "description"
            ] = route.response_description
            if (
                route_response_media_type
                and route.status_code not in STATUS_CODES_WITH_NO_BODY
            ):
                response_schema = {"type": "string"}
                if lenient_issubclass(route.response_class, JSONResponse):
                    if route.response_field:
                        response_schema, _, _ = field_schema(
                            route.response_field,
                            model_name_map=model_name_map,
                            ref_prefix=REF_PREFIX,
                        )
                    else:
                        response_schema = {}
                operation.setdefault("responses", {}).setdefault(
                    status_code, {}
                ).setdefault("content", {}).setdefault(route_response_media_type, {})[
                    "schema"
                ] = response_schema

            http422 = str(HTTP_422_UNPROCESSABLE_ENTITY)
            if (all_route_params or route.body_field) and not any(
                [
                    status in operation["responses"]
                    for status in [http422, "4XX", "default"]
                ]
            ):
                operation["responses"][http422] = {
                    "description": "Validation Error",
                    "content": {
                        "application/json": {
                            "schema": {"$ref": REF_PREFIX + "HTTPValidationError"}
                        }
                    },
                }
                if "ValidationError" not in definitions:
                    definitions.update(
                        {
                            "ValidationError": validation_error_definition,
                            "HTTPValidationError": validation_error_response_definition,
                        }
                    )
            path[method.lower()] = operation
    return path, security_schemes, definitions

async def request_body_to_args(
    required_params: List[ModelField],
    received_body: Optional[Union[Dict[str, Any], FormData]],
) -> Tuple[Dict[str, Any], List[ErrorWrapper]]:
    values = {}
    errors = []
    if required_params:
        field = required_params[0]
        field_info = get_field_info(field)
        embed = getattr(field_info, "embed", None)
        if len(required_params) == 1 and not embed:
            received_body = {field.alias: received_body}
        for field in required_params:
            value: Any = None
            if received_body is not None:
                if field.shape in sequence_shapes and isinstance(
                    received_body, FormData
                ):
                    value = received_body.getlist(field.alias)
                else:
                    value = received_body.get(field.alias)
            if (
                value is None
                or (isinstance(field_info, params.Form) and value == "")
                or (
                    isinstance(field_info, params.Form)
                    and field.shape in sequence_shapes
                    and len(value) == 0
                )
            ):
                if field.required:
                    if PYDANTIC_1:
                        errors.append(
                            ErrorWrapper(MissingError(), loc=("body", field.alias))
                        )
                    else:  # pragma: nocover
                        errors.append(
                            ErrorWrapper(  # type: ignore
                                MissingError(),
                                loc=("body", field.alias),
                                config=BaseConfig,
                            )
                        )
                else:
                    values[field.name] = deepcopy(field.default)
                continue
            if (
                isinstance(field_info, params.File)
                and lenient_issubclass(field.type_, bytes)
                and isinstance(value, UploadFile)
            ):
                value = await value.read()
            elif (
                field.shape in sequence_shapes
                and isinstance(field_info, params.File)
                and lenient_issubclass(field.type_, bytes)
                and isinstance(value, sequence_types)
            ):
                awaitables = [sub_value.read() for sub_value in value]
                contents = await asyncio.gather(*awaitables)
                value = sequence_shape_to_type[field.shape](contents)
            v_, errors_ = field.validate(value, values, loc=("body", field.alias))
            if isinstance(errors_, ErrorWrapper):
                errors.append(errors_)
            elif isinstance(errors_, list):
                errors.extend(errors_)
            else:
                values[field.name] = v_
    return values, errors

async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": exc.errors()}
    )

def get_body_field(*, dependant: Dependant, name: str) -> Optional[Field]:
    flat_dependant = get_flat_dependant(dependant)
    if not flat_dependant.body_params:
        return None
    first_param = flat_dependant.body_params[0]
    embed = getattr(first_param.schema, "embed", None)
    if len(flat_dependant.body_params) == 1 and not embed:
        return get_schema_compatible_field(field=first_param)
    model_name = "Body_" + name
    BodyModel = create_model(model_name)
    for f in flat_dependant.body_params:
        BodyModel.__fields__[f.name] = get_schema_compatible_field(field=f)
    required = any(True for f in flat_dependant.body_params if f.required)
    if any(isinstance(f.schema, params.File) for f in flat_dependant.body_params):
        BodySchema: Type[params.Body] = params.File
    elif any(isinstance(f.schema, params.Form) for f in flat_dependant.body_params):
        BodySchema = params.Form
    else:
        BodySchema = params.Body

    field = Field(
        name="body",
        type_=BodyModel,
        default=None,
        required=required,
        model_config=BaseConfig,
        class_validators={},
        alias="body",
        schema=BodySchema(None),
    )
    return field

def register_named_middleware(
    self, middleware, route_names, attach_to="request"
):
    if attach_to == "request":
        for _rn in route_names:
            if _rn not in self.named_request_middleware:
                self.named_request_middleware[_rn] = deque()
            if middleware not in self.named_request_middleware[_rn]:
                self.named_request_middleware[_rn].append(middleware)
    if attach_to == "response":
        for _rn in route_names:
            if _rn not in self.named_response_middleware:
                self.named_response_middleware[_rn] = deque()
            if middleware not in self.named_response_middleware[_rn]:
                self.named_response_middleware[_rn].append(middleware)

def url_for(self, view_name, **kwargs):
    """
    Same as :func:`sanic.Sanic.url_for`, but automatically determine
    `scheme` and `netloc` base on the request. Since this method is aiming
    to generate correct schema & netloc, `_external` is implied.

    :param kwargs: takes same parameters as in :func:`sanic.Sanic.url_for`
    :return: an absolute url to the given view
    :rtype: str
    """
    # Full URL SERVER_NAME can only be handled in app.url_for
    if "//" in self.app.config.SERVER_NAME:
        return self.app.url_for(view_name, _external=True, **kwargs)

    scheme = self.scheme
    host = self.server_name
    port = self.server_port

    if (scheme.lower() in ("http", "ws") and port == 80) or (
        scheme.lower() in ("https", "wss") and port == 443
    ):
        netloc = host
    else:
        netloc = "{}:{}".format(host, port)

    return self.app.url_for(
        view_name, _external=True, _scheme=scheme, _server=netloc, **kwargs
    )

def __getattribute__(self, code):
    msg = getattr(err_cls, code)
    return "[{code}] {msg}".format(code=code, msg=msg)

def evaluate(
    self, docs_golds, verbose=False, batch_size=256, scorer=None, component_cfg=None
):
    """Evaluate a model's pipeline components.

    docs_golds (iterable): Tuples of `Doc` and `GoldParse` objects.
    verbose (bool): Print debugging information.
    batch_size (int): Batch size to use.
    scorer (Scorer): Optional `Scorer` to use. If not passed in, a new one
        will be created.
    component_cfg (dict): An optional dictionary with extra keyword
        arguments for specific components.
    RETURNS (Scorer): The scorer containing the evaluation results.

    DOCS: https://spacy.io/api/language#evaluate
    """
    if scorer is None:
        scorer = Scorer(pipeline=self.pipeline)
    if component_cfg is None:
        component_cfg = {}
    docs, golds = zip(*docs_golds)
    docs = [
        self.make_doc(doc) if isinstance(doc, basestring_) else doc for doc in docs
    ]
    golds = list(golds)
    for name, pipe in self.pipeline:
        kwargs = component_cfg.get(name, {})
        kwargs.setdefault("batch_size", batch_size)
        if not hasattr(pipe, "pipe"):
            docs = _pipe(pipe, docs, kwargs)
        else:
            docs = pipe.pipe(docs, **kwargs)
    for doc, gold in zip(docs, golds):
        if not isinstance(gold, GoldParse):
            gold = GoldParse(doc, **gold)
        if verbose:
            print(doc)
        kwargs = component_cfg.get("scorer", {})
        kwargs.setdefault("verbose", verbose)
        scorer.score(doc, gold, **kwargs)
    return scorer

def remove_pipe(self, name):
    """Remove a component from the pipeline.

    name (unicode): Name of the component to remove.
    RETURNS (tuple): A `(name, component)` tuple of the removed component.

    DOCS: https://spacy.io/api/language#remove_pipe
    """
    if name not in self.pipe_names:
        raise ValueError(Errors.E001.format(name=name, opts=self.pipe_names))
    if ENABLE_PIPELINE_ANALYSIS:
        analyze_all_pipes(self.pipeline)
    return self.pipeline.pop(self.pipe_names.index(name))

def _read_body(self, code, headers, delegate):
    if "Content-Length" in headers:
        if "Transfer-Encoding" in headers:
            # Response cannot contain both Content-Length and
            # Transfer-Encoding headers.
            # http://tools.ietf.org/html/rfc7230#section-3.3.3
            raise httputil.HTTPInputError(
                "Response with both Transfer-Encoding and Content-Length")
        if "," in headers["Content-Length"]:
            # Proxies sometimes cause Content-Length headers to get
            # duplicated.  If all the values are identical then we can
            # use them but if they differ it's an error.
            pieces = re.split(r',\s*', headers["Content-Length"])
            if any(i != pieces[0] for i in pieces):
                raise httputil.HTTPInputError(
                    "Multiple unequal Content-Lengths: %r" %
                    headers["Content-Length"])
            headers["Content-Length"] = pieces[0]

        try:
            content_length = int(headers["Content-Length"])
        except ValueError:
            # Handles non-integer Content-Length value.
            raise httputil.HTTPInputError(
                "Only integer Content-Length is allowed: %s" % headers["Content-Length"])

        if content_length > self._max_body_size:
            raise httputil.HTTPInputError("Content-Length too long")
    else:
        content_length = None

    if code == 204:
        # This response code is not allowed to have a non-empty body,
        # and has an implicit length of zero instead of read-until-close.
        # http://www.w3.org/Protocols/rfc2616/rfc2616-sec4.html#sec4.3
        if ("Transfer-Encoding" in headers or
                content_length not in (None, 0)):
            raise httputil.HTTPInputError(
                "Response with code %d should not have body" % code)
        content_length = 0

    if content_length is not None:
        return self._read_fixed_body(content_length, delegate)
    if headers.get("Transfer-Encoding") == "chunked":
        return self._read_chunked_body(delegate)
    if self.is_client:
        return self._read_body_until_close(delegate)
    return None

def _can_keep_alive(self, start_line, headers):
    if self.params.no_keep_alive:
        return False
    connection_header = headers.get("Connection")
    if connection_header is not None:
        connection_header = connection_header.lower()
    if start_line.version == "HTTP/1.1":
        return connection_header != "close"
    elif ("Content-Length" in headers
          or headers.get("Transfer-Encoding", "").lower() == "chunked"
          or start_line.method in ("HEAD", "GET")):
        return connection_header == "keep-alive"
    return False

def initialize(self, make_current=None):
    if make_current is None:
        if IOLoop.current(instance=False) is None:
            self.make_current()
    elif make_current:
        if IOLoop.current(instance=False) is None:
            raise RuntimeError("current IOLoop already exists")
        self.make_current()

def _update_next(self, current_time):
    if self._next_timeout <= current_time:
        callback_time_sec = self.callback_time / 1000.0
        self._next_timeout += (math.floor((current_time - self._next_timeout) /
                                          callback_time_sec) + 1) * callback_time_sec

def run_in_executor(self, executor, func, *args):
    """Runs a function in a ``concurrent.futures.Executor``. If
    ``executor`` is ``None``, the IO loop's default executor will be used.

    Use `functools.partial` to pass keyword arguments to `func`.

    """
    if ThreadPoolExecutor is None:
        raise RuntimeError(
            "concurrent.futures is required to use IOLoop.run_in_executor")

    if executor is None:
        if not hasattr(self, '_executor'):
            from tornado.process import cpu_count
            self._executor = ThreadPoolExecutor(max_workers=(cpu_count() * 5))
        executor = self._executor

    return executor.submit(func, *args)

def js_to_json(code):
    def fix_kv(m):
        v = m.group(0)
        if v in ('true', 'false', 'null'):
            return v
        if v.startswith('"'):
            return v
        if v.startswith("'"):
            v = v[1:-1]
            v = re.sub(r"\\\\|\\'|\"", lambda m: {
                '\\\\': '\\\\',
                "\\'": "'",
                '"': '\\"',
            }[m.group(0)], v)
