    }

    all_formats = player_info['VSR'].values()
    # Some formats use the m3u8 protocol
    all_formats = list(filter(lambda f: f.get('videoFormat') != 'M3U8', all_formats))
    def _match_lang(f):
        if f.get('versionCode') is None:
