        # Return true if that format is in the language of the url
        if lang == 'fr':
            l = 'F'
        elif lang == 'de':
            l = 'A'
        else:
            l = lang
        regexes = [r'VO?%s' % l, r'VO?.-ST%s' % l]
        return any(re.match(r, f['versionCode']) for r in regexes)
    # Some formats may not be in the same language as the url
    # TODO: Might want not to drop videos that does not match requested language
    # but to process those formats with lower precedence
    formats = filter(_match_lang, all_formats)
    formats = list(formats)  # in python3 filter returns an iterator
    if not formats:
        # Some videos are only available in the 'Originalversion'
        # they aren't tagged as being in French or German
        # Sometimes there are neither videos of requested lang code
        # nor original version videos available
        # For such cases we just take all_formats as is
        formats = all_formats
        if not formats:
            raise ExtractorError('The formats list is empty')

    if re.match(r'[A-Z]Q', formats[0]['quality']) is not None:
        def sort_key(f):
            return ['HQ', 'MQ', 'EQ', 'SQ'].index(f['quality'])
    else:
        def sort_key(f):
            versionCode = f.get('versionCode')
            if versionCode is None:
                versionCode = ''
            return (
                # Sort first by quality
                int(f.get('height', -1)),
                int(f.get('bitrate', -1)),
                # The original version with subtitles has lower relevance
                re.match(r'VO-ST(F|A)', versionCode) is None,
                # The version with sourds/mal subtitles has also lower relevance
                re.match(r'VO?(F|A)-STM\1', versionCode) is None,
                # Prefer http downloads over m3u8
                0 if f['url'].endswith('m3u8') else 1,
            )
    formats = sorted(formats, key=sort_key)
    def _format(format_info):
        quality = ''
        height = format_info.get('height')
        if height is not None:
            quality = compat_str(height)
        bitrate = format_info.get('bitrate')
        if bitrate is not None:
            quality += '-%d' % bitrate
        if format_info.get('versionCode') is not None:
            format_id = '%s-%s' % (quality, format_info['versionCode'])
        else:
            format_id = quality
        info = {
            'format_id': format_id,
            'format_note': format_info.get('versionLibelle'),
            'width': format_info.get('width'),
            'height': height,
        }
        if format_info['mediaType'] == 'rtmp':
            info['url'] = format_info['streamer']
            info['play_path'] = 'mp4:' + format_info['url']
            info['ext'] = 'flv'
        else:
            info['url'] = format_info['url']
            info['ext'] = determine_ext(info['url'])
        return info
    info_dict['formats'] = [_format(f) for f in formats]

    return info_dict

def uppercase_escape(s):
    return re.sub(
        r'\\U[0-9a-fA-F]{8}',
        lambda m: m.group(0).decode('unicode-escape'), s)

def unescapeHTML(s):
    if s is None:
        return None
    assert type(s) == compat_str

    return re.sub(
        r'&([^;]+;)', lambda m: _htmlentity_transform(m.group(1)), s)

def _get_videos_info(self, uri):
    video_id = self._id_from_uri(uri)
    data = compat_urllib_parse.urlencode({'uri': uri})

    def fix_ampersand(s):
        """ Fix unencoded ampersand in XML """
        return s.replace(u'& ', '&amp; ')
    idoc = self._download_xml(
        self._FEED_URL + '?' + data, video_id,
        u'Downloading info', transform_source=fix_ampersand)
    return [self._get_video_info(item) for item in idoc.findall('.//item')]

def url_basename(url):
    m = re.match(r'(?:https?:|)//[^/]+/(?:[^/?#]+/)?([^/?#]+)/?(?:[?#]|$)', url)
    if not m:
        return u''
    return m.group(1)

def interpret_expression(self, expr, local_vars, allow_recursion):
    expr = expr.strip()

    if expr == '':  # Empty expression
        return None

    if expr.startswith('('):
        parens_count = 0
        for m in re.finditer(r'[()]', expr):
            if m.group(0) == '(':
                parens_count += 1
            else:
                parens_count -= 1
                if parens_count == 0:
                    sub_expr = expr[1:m.start()]
                    sub_result = self.interpret_expression(
                        sub_expr, local_vars, allow_recursion)
                    remaining_expr = expr[m.end():].strip()
                    if not remaining_expr:
                        return sub_result
                    else:
                        expr = json.dumps(sub_result) + remaining_expr
                    break
        else:
            raise ExtractorError('Premature end of parens in %r' % expr)

    for op, opfunc in _ASSIGN_OPERATORS:
        m = re.match(r'''(?x)
            (?P<out>%s)(?:\[(?P<index>[^\]]+?)\])?
            \s*%s
            (?P<expr>.*)$''' % (_NAME_RE, re.escape(op)), expr)
        if not m:
            continue
        right_val = self.interpret_expression(
            m.group('expr'), local_vars, allow_recursion - 1)

        if m.groupdict().get('index'):
            lvar = local_vars[m.group('out')]
            idx = self.interpret_expression(
                m.group('index'), local_vars, allow_recursion)
            assert isinstance(idx, int)
            cur = lvar[idx]
            val = opfunc(cur, right_val)
            lvar[idx] = val
            return val
        else:
            cur = local_vars.get(m.group('out'))
            val = opfunc(cur, right_val)
            local_vars[m.group('out')] = val
            return val

    if expr.isdigit():
        return int(expr)

    var_m = re.match(
        r'(?!if|return|true|false)(?P<name>%s)$' % _NAME_RE,
        expr)
    if var_m:
        return local_vars[var_m.group('name')]

    try:
        return json.loads(expr)
    except ValueError:
        pass

    m = re.match(
        r'(?P<var>%s)\.(?P<member>[^(]+)(?:\(+(?P<args>[^()]*)\))?$' % _NAME_RE,
        expr)
    if m:
        variable = m.group('var')
        member = m.group('member')
        arg_str = m.group('args')

        if variable in local_vars:
            obj = local_vars[variable]
        else:
            if variable not in self._objects:
                self._objects[variable] = self.extract_object(variable)
            obj = self._objects[variable]

        if arg_str is None:
            # Member access
            if member == 'length':
                return len(obj)
            return obj[member]

        assert expr.endswith(')')
        # Function call
        if arg_str == '':
            argvals = tuple()
        else:
            argvals = tuple([
                self.interpret_expression(v, local_vars, allow_recursion)
                for v in arg_str.split(',')])

        if member == 'split':
            assert argvals == ('',)
            return list(obj)
        if member == 'join':
            assert len(argvals) == 1
            return argvals[0].join(obj)
        if member == 'reverse':
            assert len(argvals) == 0
            obj.reverse()
            return obj
        if member == 'slice':
            assert len(argvals) == 1
            return obj[argvals[0]:]
        if member == 'splice':
            assert isinstance(obj, list)
            index, howMany = argvals
            res = []
            for i in range(index, min(index + howMany, len(obj))):
                res.append(obj.pop(index))
            return res

        return obj[member](argvals)

    m = re.match(
        r'(?P<in>%s)\[(?P<idx>.+)\]$' % _NAME_RE, expr)
    if m:
        val = local_vars[m.group('in')]
        idx = self.interpret_expression(
            m.group('idx'), local_vars, allow_recursion - 1)
        return val[idx]

    for op, opfunc in _OPERATORS:
        m = re.match(r'(?P<x>.+?)%s(?P<y>.+)' % re.escape(op), expr)
        if not m:
            continue
        x, abort = self.interpret_statement(
            m.group('x'), local_vars, allow_recursion - 1)
        if abort:
            raise ExtractorError(
                'Premature left-side return of %s in %r' % (op, expr))
        y, abort = self.interpret_statement(
            m.group('y'), local_vars, allow_recursion - 1)
        if abort:
            raise ExtractorError(
                'Premature right-side return of %s in %r' % (op, expr))
        return opfunc(x, y)

    m = re.match(
        r'^(?P<func>%s)\((?P<args>[a-zA-Z0-9_$,]+)\)$' % _NAME_RE, expr)
    if m:
        fname = m.group('func')
        argvals = tuple([
            int(v) if v.isdigit() else local_vars[v]
            for v in m.group('args').split(',')])
        if fname not in self._functions:
            self._functions[fname] = self.extract_function(fname)
        return self._functions[fname](argvals)

    raise ExtractorError('Unsupported JS expression %r' % expr)

def unified_timestamp(date_str, day_first=True):
    if date_str is None:
        return None

    date_str = date_str.replace(',', ' ')

    pm_delta = datetime.timedelta(hours=12 if re.search(r'(?i)PM', date_str) else 0)
    timezone, date_str = extract_timezone(date_str)

    # Remove AM/PM + timezone
    date_str = re.sub(r'(?i)\s*(?:AM|PM)(?:\s+[A-Z]+)?', '', date_str)

    for expression in date_formats(day_first):
        try:
            dt = datetime.datetime.strptime(date_str, expression) - timezone + pm_delta
            return calendar.timegm(dt.timetuple())
        except ValueError:
            pass
    timetuple = email.utils.parsedate_tz(date_str)
    if timetuple:
        return calendar.timegm(timetuple.timetuple())

def dfxp2srt(dfxp_data):
    _x = functools.partial(xpath_with_ns, ns_map={
        'ttml': 'http://www.w3.org/ns/ttml',
        'ttaf1': 'http://www.w3.org/2006/10/ttaf1',
    })

    def parse_node(node):
        str_or_empty = functools.partial(str_or_none, default='')

        out = str_or_empty(node.text)

        for child in node:
            if child.tag in (_x('ttml:br'), _x('ttaf1:br'), 'br'):
                out += '\n' + str_or_empty(child.tail)
            elif child.tag in (_x('ttml:span'), _x('ttaf1:span'), 'span'):
                out += str_or_empty(parse_node(child))
            else:
                out += str_or_empty(xml.etree.ElementTree.tostring(child))

        return out

    dfxp = compat_etree_fromstring(dfxp_data.encode('utf-8'))
    out = []
    paras = dfxp.findall(_x('.//ttml:p')) or dfxp.findall(_x('.//ttaf1:p')) or dfxp.findall('.//p')

    if not paras:
        raise ValueError('Invalid dfxp/TTML subtitle')

    for para, index in zip(paras, itertools.count(1)):
        begin_time = parse_dfxp_time_expr(para.attrib['begin'])
        end_time = parse_dfxp_time_expr(para.attrib.get('end'))
        if not end_time:
            end_time = begin_time + parse_dfxp_time_expr(para.attrib['dur'])
        out.append('%d\n%s --> %s\n%s\n\n' % (
            index,
            srt_subtitles_timecode(begin_time),
            srt_subtitles_timecode(end_time),
            parse_node(para)))

    return ''.join(out)

def parse_dfxp_time_expr(time_expr):
    if not time_expr:
        return 0.0

    mobj = re.match(r'^(?P<time_offset>\d+(?:\.\d+)?)s?$', time_expr)
    if mobj:
        return float(mobj.group('time_offset'))

    mobj = re.match(r'^(\d+):(\d\d):(\d\d(?:\.\d+)?)$', time_expr)
    if mobj:
        return 3600 * int(mobj.group(1)) + 60 * int(mobj.group(2)) + float(mobj.group(3))

def fix_kv(m):
    v = m.group(0)
    if v in ('true', 'false', 'null'):
        return v
    if v.startswith('"'):
        return v
    if v.startswith("'"):
        v = v[1:-1]
        v = re.sub(r"\\\\|\\'|\"", lambda m: {
            '\\\\': '\\\\',
            "\\'": "'",
            '"': '\\"',
        }[m.group(0)], v)
    return '"%s"' % v

def _parse_format_selection(tokens, inside_merge=False, inside_choice=False, inside_group=False):
    selectors = []
    current_selector = None
    for type, string, start, _, _ in tokens:
        # ENCODING is only defined in python 3.x
        if type == getattr(tokenize, 'ENCODING', None):
            continue
        elif type in [tokenize.NAME, tokenize.NUMBER]:
            current_selector = FormatSelector(SINGLE, string, [])
        elif type == tokenize.OP:
            if string == ')':
                if not inside_group:
                    # ')' will be handled by the parentheses group
                    tokens.restore_last_token()
                break
            elif inside_merge and string in ['/', ',']:
                tokens.restore_last_token()
                break
            elif inside_choice and string == ',':
                tokens.restore_last_token()
                break
            elif string == ',':
                selectors.append(current_selector)
                current_selector = None
            elif string == '/':
                first_choice = current_selector
                second_choice = _parse_format_selection(tokens, inside_choice=True)
                current_selector = None
                selectors.append(FormatSelector(PICKFIRST, (first_choice, second_choice), []))
            elif string == '[':
                if not current_selector:
                    current_selector = FormatSelector(SINGLE, 'best', [])
                format_filter = _parse_filter(tokens)
                current_selector.filters.append(format_filter)
            elif string == '(':
                if current_selector:
                    raise syntax_error('Unexpected "("', start)
                group = _parse_format_selection(tokens, inside_group=True)
                current_selector = FormatSelector(GROUP, group, [])
            elif string == '+':
                video_selector = current_selector
                audio_selector = _parse_format_selection(tokens, inside_merge=True)
                current_selector = FormatSelector(MERGE, (video_selector, audio_selector), [])
            else:
                raise syntax_error('Operator not recognized: "{0}"'.format(string), start)
        elif type == tokenize.ENDMARKER:
            break
    if current_selector:
        selectors.append(current_selector)
    return selectors

def _parse_format_selection(tokens, endwith=[]):
    selectors = []
    current_selector = None
    for type, string, start, _, _ in tokens:
        # ENCODING is only defined in python 3.x
        if type == getattr(tokenize, 'ENCODING', None):
            continue
        elif type in [tokenize.NAME, tokenize.NUMBER]:
            current_selector = FormatSelector(SINGLE, string, [])
        elif type == tokenize.OP:
            if string in endwith:
                break
            elif string == ')':
                # ')' will be handled by the parentheses group
                tokens.restore_last_token()
                break
            if string == ',':
                selectors.append(current_selector)
                current_selector = None
            elif string == '/':
                first_choice = current_selector
                second_choice = _parse_format_selection(tokens, [','])
                current_selector = None
                selectors.append(FormatSelector(PICKFIRST, (first_choice, second_choice), []))
            elif string == '[':
                if not current_selector:
                    current_selector = FormatSelector(SINGLE, 'best', [])
                format_filter = _parse_filter(tokens)
                current_selector.filters.append(format_filter)
            elif string == '(':
                if current_selector:
                    raise syntax_error('Unexpected "("', start)
                current_selector = FormatSelector(GROUP, _parse_format_selection(tokens, [')']), [])
            elif string == '+':
                video_selector = current_selector
                audio_selector = _parse_format_selection(tokens, [','])
                current_selector = None
                selectors.append(FormatSelector(MERGE, (video_selector, audio_selector), []))
            else:
                raise syntax_error('Operator not recognized: "{0}"'.format(string), start)
        elif type == tokenize.ENDMARKER:
            break
    if current_selector:
        selectors.append(current_selector)
    return selectors

def build(self):
    g = Grammar(self.tokens)

    for level, (assoc, terms) in enumerate(self.precedence, 1):
        for term in terms:
            g.set_precedence(term, assoc, level)

    for prod_name, syms, func, precedence in self.productions:
        g.add_production(prod_name, syms, func, precedence)

    g.set_start()

    for unused_term in g.unused_terminals():
        warnings.warn(
            "Token %r is unused" % unused_term,
            ParserGeneratorWarning,
            stacklevel=2
        )
    for unused_prod in g.unused_productions():
        warnings.warn(
            "Production %r is not reachable" % unused_prod,
            ParserGeneratorWarning,
            stacklevel=2
        )

    g.build_lritems()
    g.compute_first()
    g.compute_follow()

    cache_file = os.path.join(
        tempfile.gettempdir(),
        "rply-%s-%s-%s.json" % (self.VERSION, self.cache_id, self.compute_grammar_hash(g))
    )
    table = None
    if os.path.exists(cache_file):
        with open(cache_file) as f:
            data = json.load(f)
        if self.data_is_valid(g, data):
            table = LRTable.from_cache(g, data)
    if table is None:
        table = LRTable.from_grammar(g)
        with open(cache_file, "w") as f:
            json.dump(self.serialize_table(table), f)
    if table.sr_conflicts:
        warnings.warn(
            "%d shift/reduce conflict%s" % (len(table.sr_conflicts), "s" if len(table.sr_conflicts) > 1 else ""),
            ParserGeneratorWarning,
            stacklevel=2,
        )
    if table.rr_conflicts:
        warnings.warn(
            "%d reduce/reduce conflict%s" % (len(table.rr_conflicts), "s" if len(table.rr_conflicts) > 1 else ""),
            ParserGeneratorWarning,
            stacklevel=2,
        )
    return LRParser(table, self.error_handler)

def __call__(self, env, start_response):
    try:
        # Validate the method
        method = env["REQUEST_METHOD"].upper()
        if method != "POST":
            raise HTTPException(405, "Method not allowed (%s)." % method)

        # Parse the request
        try:
            length = int(env["CONTENT_LENGTH"])
        except AttributeError:
            length = -1
        try:
            pr = codec.decode(env["wsgi.input"].read(length))
        except codec.ParsingError as e:
            raise HTTPException(400, e.message)

        # Find the remote proxy
        servers = self.__resolver.lookup(
            pr.realm,
            kpasswd=isinstance(pr, codec.KPASSWDProxyRequest)
        )
        if not servers:
            raise HTTPException(503, "Can't find remote (%s)." % pr)

        # Contact the remote server
        reply = None
        wsocks = []
        rsocks = []
        for server in map(urlparse.urlparse, servers):
            # Enforce valid, supported URIs
            scheme = server.scheme.lower().split("+", 1)
            if scheme[0] not in ("kerberos", "kpasswd"):
                continue
            if len(scheme) > 1 and scheme[1] not in ("tcp", "udp"):
                continue

            # Do the DNS lookup
            try:
                port = server.port
                if port is None:
                    port = scheme[0]
                addrs = socket.getaddrinfo(server.hostname, port)
            except socket.gaierror:
                continue

            # Sort addresses so that we get TCP first.
            #
            # Stick a None address on the end so we can get one
            # more attempt after all servers have been contacted.
            addrs = tuple(sorted(filter(self.__filter_addr, addrs)))
            for addr in addrs + (None,):
                if addr is not None:
                    # Bypass unspecified socktypes
                    if (len(scheme) > 1
                            and addr[1] != self.SOCKTYPES[scheme[1]]):
                        continue

                    # Create the socket
                    sock = socket.socket(*addr[:3])
                    sock.setblocking(0)

                    # Connect
                    try:
                        # In Python 2.x, non-blocking connect() throws
                        # socket.error() with errno == EINPROGRESS. In
                        # Python 3.x, it throws io.BlockingIOError().
                        sock.connect(addr[4])
                    except socket.error as e:
                        if e.errno != 115:  # errno != EINPROGRESS
                            sock.close()
                            continue
                    except io.BlockingIOError:
                        pass
                    wsocks.append(sock)

                # Resend packets to UDP servers
                for sock in tuple(rsocks):
                    if self.sock_type(sock) == socket.SOCK_DGRAM:
                        wsocks.append(sock)
                        rsocks.remove(sock)

                # Call select()
                timeout = time.time() + (15 if addr is None else 2)
                reply = self.__await_reply(pr, rsocks, wsocks, timeout)
                if reply is not None:
                    break

            if reply is not None:
                break

        for sock in rsocks + wsocks:
            sock.close()

        if reply is None:
            raise HTTPException(503, "Remote unavailable (%s)." % pr)

        # Return the result to the client
        raise HTTPException(200, codec.encode(reply),
                            [("Content-Type", "application/kerberos")])
    except HTTPException as e:
        start_response(str(e), e.headers)
        return [e.message]

def skip(self, type):
    if type == TType.STOP:
        return
    elif type == TType.BOOL:
        self.readBool()
    elif type == TType.BYTE:
        self.readByte()
    elif type == TType.I16:
        self.readI16()
    elif type == TType.I32:
        self.readI32()
    elif type == TType.I64:
        self.readI64()
    elif type == TType.DOUBLE:
        self.readDouble()
    elif type == TType.FLOAT:
        self.readFloat()
    elif type == TType.STRING:
        self.readString()
    elif type == TType.STRUCT:
        name = self.readStructBegin()
        while True:
            (name, type, id) = self.readFieldBegin()
            if type == TType.STOP:
                break
            self.skip(type)
            self.readFieldEnd()
        self.readStructEnd()
    elif type == TType.MAP:
        (ktype, vtype, size) = self.readMapBegin()
        for _ in range(size):
            self.skip(ktype)
            self.skip(vtype)
        self.readMapEnd()
    elif type == TType.SET:
        (etype, size) = self.readSetBegin()
        for _ in range(size):
            self.skip(etype)
        self.readSetEnd()
    elif type == TType.LIST:
        (etype, size) = self.readListBegin()
        for _ in range(size):
            self.skip(etype)
        self.readListEnd()

async def app(request: Request) -> Response:
    try:
        body = None
        if body_field:
            if is_body_form:
                body = await request.form()
            else:
                body_bytes = await request.body()
                if body_bytes:
                    body = await request.json()
    except json.JSONDecodeError as e:
        raise RequestValidationError([ErrorWrapper(e, ("body", e.pos))], body=e.doc)
    except Exception as e:
        raise HTTPException(
            status_code=400, detail="There was an error parsing the body"
        ) from e
    solved_result = await solve_dependencies(
        request=request,
        dependant=dependant,
        body=body,
        dependency_overrides_provider=dependency_overrides_provider,
    )
    values, errors, background_tasks, sub_response, _ = solved_result
    if errors:
        raise RequestValidationError(errors, body=body)
    else:
        raw_response = await run_endpoint_function(
            dependant=dependant, values=values, is_coroutine=is_coroutine
        )

        if isinstance(raw_response, Response):
            if raw_response.background is None:
                raw_response.background = background_tasks
            return raw_response
        response_data = await serialize_response(
            field=response_field,
            response_content=raw_response,
            include=response_model_include,
            exclude=response_model_exclude,
            by_alias=response_model_by_alias,
            exclude_unset=response_model_exclude_unset,
            exclude_defaults=response_model_exclude_defaults,
            exclude_none=response_model_exclude_none,
            is_coroutine=is_coroutine,
        )
        response = actual_response_class(
            content=response_data,
            status_code=status_code,
            background=background_tasks,  # type: ignore # in Starlette
        )
        response.headers.raw.extend(sub_response.headers.raw)
        if sub_response.status_code:
            response.status_code = sub_response.status_code
        return response

def prepare_key(self, key):

    if isinstance(
        key,
        (Ed25519PrivateKey, Ed25519PublicKey, Ed448PrivateKey, Ed448PublicKey),
    ):
        return key

    if isinstance(key, (bytes, str)):
        if isinstance(key, str):
            key = key.encode("utf-8")
        str_key = key.decode("utf-8")

        if "-----BEGIN PUBLIC" in str_key:
            return load_pem_public_key(key)
        if "-----BEGIN PRIVATE" in str_key:
            return load_pem_private_key(key, password=None)
        if str_key[0:4] == "ssh-":
            return load_ssh_public_key(key)

    raise TypeError("Expecting a PEM-formatted or OpenSSH key.")

@csrf_protect
def password_reset(request, is_admin_site=False,
                   template_name='registration/password_reset_form.html',
                   email_template_name='registration/password_reset_email.html',
                   subject_template_name='registration/password_reset_subject.txt',
                   password_reset_form=PasswordResetForm,
                   token_generator=default_token_generator,
                   post_reset_redirect=None,
                   from_email=None,
                   current_app=None,
                   extra_context=None):
    if post_reset_redirect is None:
        post_reset_redirect = reverse('django.contrib.auth.views.password_reset_done')
    if request.method == "POST":
        form = password_reset_form(request.POST)
        if form.is_valid():
            opts = {
                'use_https': request.is_secure(),
                'token_generator': token_generator,
                'from_email': from_email,
                'email_template_name': email_template_name,
                'subject_template_name': subject_template_name,
                'request': request,
            }
            if is_admin_site:
                opts = dict(opts, domain_override=request.META['HTTP_HOST'])
            form.save(**opts)
            return HttpResponseRedirect(post_reset_redirect)
    else:
        form = password_reset_form()
    context = {
        'form': form,
    }
    if extra_context is not None:
        context.update(extra_context)
    return TemplateResponse(request, template_name, context,
                            current_app=current_app)

