@register.filter
def json_dumps(value, indent=None):
    if isinstance(value, QuerySet):
        result = serialize('json', value, indent=indent)
    else:
        result = json.dumps(value, indent=indent, cls=DjbletsJSONEncoder)

    return mark_safe(result)

def constructObject(data):
    try:
        classBase = eval(data[""] + "." + data[""].title())
    except NameError:
        logger.error("Don't know how to handle message type: \"%s\"", data[""])
        return None
    try:
        returnObj = classBase()
        returnObj.decode(data)
    except KeyError as e:
        logger.error("Missing mandatory key %s", e)
        return None
    except:
        logger.error("classBase fail", exc_info=True)
        return None
    else:
        return returnObj

def validate_request(self, request):
    """If configured for webhook basic auth, validate request has correct auth."""
    if self.basic_auth:
        basic_auth = get_request_basic_auth(request)
        if basic_auth is None or basic_auth not in self.basic_auth:
            # noinspection PyUnresolvedReferences
            raise AnymailWebhookValidationFailure(
                "Missing or invalid basic auth in Anymail %s webhook" % self.esp_name)

def authenticate(self, username, password):
    child = None
    try:
        child = pexpect.spawn('/bin/sh', ['-c', '/bin/su -c "/bin/echo SUCCESS" - %s' % username], timeout=5)
        child.expect('.*:')
        child.sendline(password)
        result = child.expect(['su: .*', 'SUCCESS'])
    except Exception as err:
        if child and child.isalive():
            child.close()
        logging.error('Error checking password: %s', err)
        return False
    if result == 0:
        return False
    else:
        return True

def send_nscript(title, msg, gtype, force=False, test=None):
    """Run user's notification script"""
    if test:
        script = test.get("nscript_script")
        nscript_parameters = test.get("nscript_parameters")
    else:
        script = sabnzbd.cfg.nscript_script()
        nscript_parameters = sabnzbd.cfg.nscript_parameters()
    nscript_parameters = nscript_parameters.split()
    if not script:
        return T("Cannot send, missing required data")
    title = "SABnzbd: " + T(NOTIFICATION.get(gtype, "other"))

    if force or check_classes(gtype, "nscript"):
        script_path = make_script_path(script)
        if script_path:
            ret = -1
            output = None
            try:
                p = build_and_run_command([script_path, gtype, title, msg] + nscript_parameters, env=create_env())
                output = p.stdout.read()
                ret = p.wait()
            except:
                logging.info("Failed script %s, Traceback: ", script, exc_info=True)

            if ret:
                logging.error(T('Script returned exit code %s and output "%s"'), ret, output)
                return T('Script returned exit code %s and output "%s"') % (ret, output)
            else:
                logging.info("Successfully executed notification script %s", script_path)
        else:
            return T('Notification script "%s" does not exist') % script_path
    return ""

def write_error(self, status_code: int, **kwargs: Any) -> None:
    """APIHandler errors are JSON, not human pages"""
    self.set_header("Content-Type", "application/json")
    message = responses.get(status_code, "Unknown HTTP Error")
    reply: dict[str, Any] = {
        "message": message,
    }
    exc_info = kwargs.get("exc_info")
    if exc_info:
        e = exc_info[1]
        if isinstance(e, HTTPError):
            reply["message"] = e.log_message or message
            reply["reason"] = e.reason
        else:
            reply["message"] = "Unhandled error"
            reply["reason"] = None
            reply["traceback"] = "".join(traceback.format_exception(*exc_info))
    self.log.warning("wrote error: %r", reply["message"], exc_info=True)
    self.finish(json.dumps(reply))

@web.authenticated
@authorized
async def post(self, kernel_id, action):
    """Interrupt or restart a kernel."""
    km = self.kernel_manager
    if action == "interrupt":
        await ensure_async(km.interrupt_kernel(kernel_id))  # type:ignore[func-returns-value]
        self.set_status(204)
    if action == "restart":
        try:
            await km.restart_kernel(kernel_id)
        except Exception as e:
            message = "Exception restarting kernel"
            self.log.error(message, exc_info=True)
            traceback = format_tb(e.__traceback__)
            self.write(json.dumps({"message": message, "traceback": traceback}))
            self.set_status(500)
        else:
            model = await ensure_async(km.kernel_model(kernel_id))
            self.write(json.dumps(model, default=json_default))
    self.finish()

