async def _handle(self, request: Request) -> StreamResponse:
    rel_url = request.match_info["filename"]
    try:
        filename = Path(rel_url)
        if filename.anchor:
            # rel_url is an absolute name like
            # /static/\\machine_name\c$ or /static/D:\path
            # where the static dir is totally different
            raise HTTPForbidden()
        filepath = self._directory.joinpath(filename).resolve()
        if not self._follow_symlinks:
            filepath.relative_to(self._directory)
    except (ValueError, FileNotFoundError) as error:
        # relatively safe
        raise HTTPNotFound() from error
    except HTTPForbidden:
        raise
    except Exception as error:
        # perm error or other kind!
        request.app.logger.exception(error)
        raise HTTPNotFound() from error

    # on opening a dir, load its contents if allowed
    if filepath.is_dir():
        if self._show_index:
            try:
                return Response(
                    text=self._directory_as_html(filepath), content_type="text/html"
                )
            except PermissionError:
                raise HTTPForbidden()
        else:
            raise HTTPForbidden()
    elif filepath.is_file():
        return FileResponse(filepath, chunk_size=self._chunk_size)
    else:
        raise HTTPNotFound

@security.private
def _ensureSnapshotsFolder(self, subdir=None):
    """ Ensure that the appropriate snapshot folder exists.
    """
    path = ['snapshots', self._snapshot_id]

    if subdir is not None:
        path.extend(subdir.split('/'))

    current = self._tool

    for element in path:

        if element not in current.objectIds():
            # No Unicode IDs!
            current._setObject(str(element), Folder(element))

        current = current._getOb(element)

    return current

@login_required()
@render_response()
def load_metadata_preview(request, c_type, c_id, conn=None, share_id=None, **kwargs):
    """
    This is the image 'Preview' tab for the right-hand panel.
    """
    context = {}

    # the index of a field within a well
    index = getIntOrDefault(request, "index", 0)

    manager = BaseContainer(conn, **{str(c_type): long(c_id)})
    if share_id:
        context["share"] = BaseShare(conn, share_id)
    if c_type == "well":
        manager.image = manager.well.getImage(index)

    allRdefs = manager.image.getAllRenderingDefs()
    rdefs = {}
    rdefId = manager.image.getRenderingDefId()
    # remove duplicates per user
    for r in allRdefs:
        ownerId = r["owner"]["id"]
        r["current"] = r["id"] == rdefId
        # if duplicate rdefs for user, pick one with highest ID
        if ownerId not in rdefs or rdefs[ownerId]["id"] < r["id"]:
            rdefs[ownerId] = r
    rdefs = rdefs.values()
    # format into rdef strings,
    # E.g. {c: '1|3118:35825$FF0000,2|2086:18975$FFFF00', m: 'c'}
    rdefQueries = []
    for r in rdefs:
        chs = []
        for i, c in enumerate(r["c"]):
            act = "-"
            if c["active"]:
                act = ""
            color = c["lut"] if "lut" in c else c["color"]
            reverse = "r" if c["inverted"] else "-r"
            chs.append(
                "%s%s|%s:%s%s$%s" % (act, i + 1, c["start"], c["end"], reverse, color)
            )
        rdefQueries.append(
            {
                "id": r["id"],
                "owner": r["owner"],
                "c": ",".join(chs),
                "m": r["model"] == "greyscale" and "g" or "c",
            }
        )
    max_w, max_h = conn.getMaxPlaneSize()
    size_x = manager.image.getSizeX()
    size_y = manager.image.getSizeY()

    context["tiledImage"] = (size_x * size_y) > (max_w * max_h)
    context["manager"] = manager
    context["rdefsJson"] = json.dumps(rdefQueries)
    context["rdefs"] = rdefs
    context["template"] = "webclient/annotations/metadata_preview.html"
    return context

@commands.guild_only()
@vc.command()
async def hidden(self, ctx: commands.Context, true_or_false: Optional[bool] = True):
    """Hide or unhide a voicechannel you own."""
    data = await self.config.guild(ctx.guild).pchannels()
    try:
        for key in data:
            if data[key] == ctx.author.voice.channel.id:
                ov = {
                    ctx.guild.default_role: discord.PermissionOverwrite(
                        view_channel=False, connect=False
                    ),
                    ctx.author: discord.PermissionOverwrite(
                        view_channel=True, connect=True, speak=True, manage_channels=True
                    ),
                }
                if self.invoiceConfig:
                    ov[
                        ctx.guild.get_role(
                            await self.invoiceConfig.channel(ctx.author.voice.channel).role()
                        )
                    ] = discord.PermissionOverwrite(
                        view_channel=True, connect=True, speak=True
                    )
                await ctx.author.voice.channel.edit(overwrites=ov)
        await ctx.tick()
        await ctx.send(_("VC has been hidden successfully."))
    except AttributeError:
        return await ctx.send(_("You need to be in a VC to do this."))

def parse_jwt_token(request: func.HttpRequest) -> Result[UserInfo]:
    """Obtains the Access Token from the Authorization Header"""
    token_str = get_auth_token(request)
    if token_str is None:
        return Error(
            code=ErrorCode.INVALID_REQUEST,
            errors=["unable to find authorization token"],
        )

    # This token has already been verified by the azure authentication layer
    token = jwt.decode(token_str, options={"verify_signature": False})

    application_id = UUID(token["appid"]) if "appid" in token else None
    object_id = UUID(token["oid"]) if "oid" in token else None
    upn = token.get("upn")
    return UserInfo(application_id=application_id, object_id=object_id, upn=upn)

def _get_shared_models(self, args: "DictConfig") -> Dict[str, dict]:
