def _rpsl_db_query_to_graphql_out(query: RPSLDatabaseQuery, info: GraphQLResolveInfo):
    """
    Given an RPSL database query, execute it and clean up the output
    to be suitable to return to GraphQL.

    Main changes are:
    - Enum handling
    - Adding the asn and prefix fields if applicable
    - Ensuring the right fields are returned as a list of strings or a string
    """
    database_handler = info.context['request'].app.state.database_handler
    if info.context.get('sql_trace'):
        if 'sql_queries' not in info.context:
            info.context['sql_queries'] = [repr(query)]
        else:
            info.context['sql_queries'].append(repr(query))

    for row in database_handler.execute_query(query, refresh_on_error=True):
        graphql_result = {snake_to_camel_case(k): v for k, v in row.items() if k != 'parsed_data'}
        if 'object_text' in row:
            graphql_result['objectText'] = remove_auth_hashes(row['object_text'])
        if 'rpki_status' in row:
            graphql_result['rpkiStatus'] = row['rpki_status']
        if row.get('ip_first') is not None and row.get('prefix_length'):
            graphql_result['prefix'] = row['ip_first'] + '/' + str(row['prefix_length'])
        if row.get('asn_first') is not None and row.get('asn_first') == row.get('asn_last'):
            graphql_result['asn'] = row['asn_first']

        object_type = resolve_rpsl_object_type(row)
        for key, value in row.get('parsed_data', dict()).items():
            if key == 'auth':
                value = remove_auth_hashes(value)
            graphql_type = schema.graphql_types[object_type][key]
            if graphql_type == 'String' and isinstance(value, list):
                value = '\n'.join(value)
            graphql_result[snake_to_camel_case(key)] = value
        yield graphql_result

def remove_auth_hashes(input: Optional[str]):
    if not input:
        return input
    # If there are no hashes, skip the RE for performance.
    if not any([pw_hash in input for pw_hash in PASSWORD_HASHERS_ALL.keys()]):
        return input
    return re_remove_passwords.sub(r'\1 %s  # Filtered for security' % PASSWORD_HASH_DUMMY_VALUE, input)

def get_csv_incident_list(self) -> str:
    csvOutput = io.StringIO()
    writer = csv.writer(csvOutput)

    if len(self.triggered_details.hits) > 0:  # pragma: no cover
        hit_class_dict = dict(self.triggered_details.hits[0])
        headers = [
            (i)
            for i in hit_class_dict.keys()
            if i not in ["token_type", "time_of_hit"]
        ]
        writer.writerow(["Timestamp"] + headers)
        for hit in self.triggered_details.hits:
            timestamp = hit.time_of_hit
            hit_id = datetime.fromtimestamp(timestamp).strftime(
                "%Y-%m-%d %H:%M:%S.%f"
            )
            hit_dict = dict(hit)
            data = [hit_id]
            for key in headers:
                data.append(hit_dict.get(key, "N/A"))
            writer.writerow(data)
    else:
        writer.writerow("the token has not been triggered")

    return csvOutput.getvalue()

def handle_login(
    redirect_type: str = "client",
) -> Response | Tuple[Response, Literal[401]] | None:

    # Returns a shallow mutable copy of the immutable
    # multi dict.
    request_args = request.args.copy()
    redirect_url = request_args.pop("redirect_url", "/")
    query_args = "&".join(
        [arg + "=" + value for arg, value in request_args.items()]
    )
    if query_args:
        redirect_url += "?" + query_args

    if is_authenticated(request):
        return redirect_response(redirect_url, redirect_type)

    if request.method == "POST":
        token_creation_limit = datetime.datetime.utcnow() - datetime.timedelta(
            hours=app.config["TOKEN_DURATION_HOURS"]
        )
        # Remove outdated tokens.
        Token.query.filter(Token.created < token_creation_limit).delete()

        username = request.form.get("username")
        password = request.form.get("password")
        token = request.form.get("token")

        # Check whether the given user exists.
        user = User.query.filter(User.username == username).first()

        invalid_login_msg = "Username password combination does not exist."
        if user is None:
            return jsonify({"error": invalid_login_msg}), 401
        else:
            if password is not None:
                can_login = check_password_hash(user.password_hash, password)
            elif token is not None and user.token_hash is not None:
                can_login = check_password_hash(user.token_hash, token)
            else:
                can_login = False

            if can_login:

                token = Token(user=user.uuid, token=str(secrets.token_hex(16)))

                db.session.add(token)
                db.session.commit()

                resp = redirect_response(redirect_url, redirect_type)
                resp.set_cookie("auth_token", token.token)
                resp.set_cookie("auth_username", username)

                return resp

            else:
                return jsonify({"error": invalid_login_msg}), 401

def receive_data(self, s):
    save_path = prefs.get_save_path()

    path = os.path.join(save_path, s.relative_path)
    if path != self.current_path:
        self.close_current_file()
        self.current_path = path
        self.current_mode = s.file_mode
        self.current_type = s.file_type
        self.current_mtime = s.time.mtime
        self.current_mtime_usec = s.time.mtime_usec

    if not self.current_gfile:
        self.current_gfile = Gio.File.new_for_path(path)
        # Check for valid path (GFile resolves paths upon creation).
        if self.save_path_file.get_relative_path(self.current_gfile) is None:
            raise Exception(_("Resolved path is not valid: %s -> %s") % (path, self.current_gfile.get_path()))

    if s.file_type == FileType.DIRECTORY:
        os.makedirs(path, exist_ok=True)
    elif s.file_type == FileType.SYMBOLIC_LINK:
        make_symbolic_link(self.op, path, s.symlink_target)
    else:
        if self.current_stream == None:
            self.current_stream = self.current_gfile.create(Gio.FileCreateFlags.NONE, None)

        if not s.chunk:
            return

        self.current_stream.write_bytes(GLib.Bytes(s.chunk), None)
        self.op.progress_tracker.update_progress(len(s.chunk))

def renderCell(self, item):
    value = get_value(item, self.attribute, default=())

    if not isinstance(value, (list, tuple)):
        value = (value,)

    gtool = getToolByName(plone.api.portal.get(), 'portal_groups')
    mtool = getToolByName(plone.api.portal.get(), 'portal_membership')
    principals = []
    for principal_id in value:
        user = mtool.getMemberById(principal_id)
        if user is not None:
            principals.append(user.getProperty('fullname', None) or user.getId())
        else:
            group = gtool.getGroupById(principal_id)
            if group is not None:
                principals.append(group.getProperty('title', None) or group.getId())

    return ', '.join(principals).decode('utf-8')

def getLinkContent(self, item):
    title = get_value(item, 'Title')
    if isinstance(title, unicode):
        return title
    else:
        return unicode(title, 'utf-8', 'ignore')

def renderCell(self, value):
    username = getattr(value, self.field, '')
    if username and username != EMPTY_STRING:
        member = api.user.get(username)
        return member.getUser().getProperty('fullname').decode('utf-8')

    return ""

def safer_getattr(object, name, default=None, getattr=getattr):
    """Getattr implementation which prevents using format on string objects.

    format() is considered harmful:
    http://lucumr.pocoo.org/2016/12/29/careful-with-str-format/

    """
    if isinstance(object, str) and name == 'format':
        raise NotImplementedError(
            'Using format() on a %s is not safe.' % object.__class__.__name__)
    if name.startswith('_'):
        raise AttributeError(
            '"{name}" is an invalid attribute name because it '
            'starts with "_"'.format(name=name)
        )
    return getattr(object, name, default)

def post(self, request, *args, **kwargs):
    content = request.POST.get("content", "")
    lexer = request.POST.get("lexer", highlight.LEXER_DEFAULT).strip()
    filename = request.POST.get("filename", "").strip()
    expires = request.POST.get("expires", "").strip()
    response_format = request.POST.get("format", "default").strip()

    if not content.strip():
        return HttpResponseBadRequest("No content given")

    # We need at least a lexer or a filename
    if not lexer and not filename:
        return HttpResponseBadRequest(
            "No lexer or filename given. Unable to "
            "determine a highlight. Valid lexers are: %s"
            % ", ".join(highlight.LEXER_KEYS)
        )

    # A lexer is given, check if its valid at all
    if lexer and lexer not in highlight.LEXER_KEYS:
        return HttpResponseBadRequest(
            'Invalid lexer "%s" given. Valid lexers are: %s'
            % (lexer, ", ".join(highlight.LEXER_KEYS))
        )

    # No lexer is given, but we have a filename, try to get the lexer
    #  out of it. In case Pygments cannot determine the lexer of the
    # filename, we fallback to 'plain' code.
    if not lexer and filename:
        try:
            lexer_cls = get_lexer_for_filename(filename)
            lexer = lexer_cls.aliases[0]
        except (ClassNotFound, IndexError):
            lexer = config.PLAIN_CODE_SYMBOL

    if expires:
        expire_options = [str(i) for i in dict(config.EXPIRE_CHOICES)]
        if expires not in expire_options:
            return HttpResponseBadRequest(
                'Invalid expire choice "{}" given. Valid values are: {}'.format(
                    expires, ", ".join(expire_options)
                )
            )
        expires, expire_type = get_expire_values(expires)
    else:
        expires = datetime.datetime.now() + datetime.timedelta(seconds=60 * 60 * 24)
        expire_type = Snippet.EXPIRE_TIME

    snippet = Snippet.objects.create(
        content=content,
        lexer=lexer,
        expires=expires,
        expire_type=expire_type,
    )

    # Custom formatter for the API response
    formatter = getattr(self, f"_format_{response_format}", None)
    if callable(formatter):
        return HttpResponse(formatter(snippet))

    # Otherwise use the default one.
    return HttpResponse(self._format_default(snippet))

async def get(self, request: web.Request) -> web.Response:
    """Return a list of persons if request comes from a local IP."""
    try:
        remote_address = ip_address(request.remote)  # type: ignore[arg-type]
    except ValueError:
        return self.json_message(
            message="Invalid remote IP",
            status_code=HTTPStatus.BAD_REQUEST,
            message_code="invalid_remote_ip",
        )

    hass: HomeAssistant = request.app["hass"]
    if is_cloud_connection(hass) or not is_local(remote_address):
        return self.json_message(
            message="Not local",
            status_code=HTTPStatus.BAD_REQUEST,
            message_code="not_local",
        )

    yaml, storage, _ = hass.data[DOMAIN]
    persons = [*yaml.async_items(), *storage.async_items()]

    return self.json(
        {
            person[ATTR_USER_ID]: {
                ATTR_NAME: person[ATTR_NAME],
                CONF_PICTURE: person.get(CONF_PICTURE),
            }
            for person in persons
            if person.get(ATTR_USER_ID)
        }
    )

def pipeline_files_upload(self, base_path, file_handle, case_customer, case_name, is_update):
    """
    Handle the files for a specific
    :return:
    """

    if base_path and Path(base_path).is_dir:
        file_handle.save(Path(base_path, file_handle.filename))
        return InterfaceStatus.I2Success("Successfully saved file {} to {}".format(file_handle.filename, base_path))

    else:
        return InterfaceStatus.I2Error("Directory {} not found. Can't save file".format(base_path))
